// Chapter 1 — EMS Systems.
// Sourced to the National EMS Scope of Practice Model and the Education
// Standards. Kansas scope and AMR KC standing orders are deliberately NOT
// here: they belong in local_overlay so the base module stays portable.
const SOP='National EMS Scope of Practice Model (NHTSA, 2019; 2021 update) — AEMT.';
const STD='NHTSA National EMS Education Standards (2021) — Preparatory: EMS Systems.';
const NR='NREMT Advanced EMT Examination Specifications, effective 1 July 2024.';

const opt=(id,text,correct,rationale)=>({id,text,correct,rationale});
const base=(o)=>({stimulus:{kind:'none',ref:null},bloom:'apply',nremt_domain:'ems_operations',
  cj_step:null,difficulty_seed:0.5,high_stakes:false,reviewed_by:null,
  review_status:'unreviewed',version:'1.0.0',...o});

export const objectives=[
 {id:'obj-1.1.a',chapter:1,tier:'core',text:'Distinguish EMR, EMT, AEMT and Paramedic by scope, and state what AEMT adds',
  enables:'Know before you act whether a skill is yours to perform or one you must call for'},
 {id:'obj-1.2.a',chapter:1,tier:'core',text:'Differentiate scope of practice, standard of care, protocol, and licensure, certification and credentialing',
  enables:'Recognise when an instruction you have been given would take you outside your scope'},
 {id:'obj-1.3.a',chapter:1,tier:'core',text:'Identify the components of an EMS system and how a call moves through them',
  enables:'Know who to ask for what when something on a call is not going to plan'},
 {id:'obj-1.4.a',chapter:1,tier:'core',text:'Differentiate online from offline medical direction and apply standing orders',
  enables:'Act on a standing order without delay, and know the point at which you must call'},
 {id:'obj-1.5.a',chapter:1,tier:'core',text:'Apply destination logic using specialty centre capability and transfer requirements',
  enables:'Choose a destination that can actually treat the problem, rather than the nearest door'},
 {id:'obj-1.6.a',chapter:1,tier:'core',text:'Explain continuous quality improvement and how evidence changes practice',
  enables:'Read a practice change and judge what it rests on, instead of taking it on authority'},
 {id:'obj-1.7.a',chapter:1,tier:'context',text:'Describe professional attributes and define mobile integrated healthcare',
  enables:'Recognise the conduct that keeps a licence, and what MIH asks of a crew'},
 {id:'obj-1.INT.a',chapter:1,tier:'core',text:'Integrate scope, medical direction and destination on a single call',
  enables:'Hold all three together under time pressure, which is when they conflict'}
];

